def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    remaining = 100 - n

    if n < 5:
        if last_opp == 'D':
            return 'D' if n >= 2 and opp[-2] == 'D' else 'C'
        return 'C'

    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')
    opp_def10 = sum(1 for a in opp[-10:] if a == 'D')
    my_def10 = sum(1 for a in me[-10:] if a == 'D')

    if remaining <= 3:
        return 'D'

    if opp_def10 >= 8 or opp_def >= n * 0.85:
        return 'D'

    if n >= 20 and opp_def10 <= 1 and my_def10 <= 2:
        if remaining <= 8 and opp_def <= 1:
            return 'D'
        return 'C'

    if opp_def == 0 and n >= 15:
        if remaining <= 12:
            return 'D' if rng.random() < 0.5 else 'C'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    if n >= 20:
        recent = sum(1 for a in opp[-4:] if a == 'D')
        earlier = sum(1 for a in opp[-15:-4] if a == 'D')
        if recent >= 3 and earlier <= 1:
            return 'D'

    if last_opp == 'D' and last_me == 'C':
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            return 'D'
        if opp_def <= max(2, n * 0.15):
            return 'C'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if last_opp == 'D' and last_me == 'D':
        if n >= 3 and opp[-2] == 'C':
            return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if my_def10 >= 6:
            if rng.random() < 0.4:
                return 'C'
        if opp_def10 >= 4:
            if rng.random() < 0.2:
                return 'D'
        return 'C'

    return 'C'
